import{_ as t,o as i,c as r,a2 as l}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"CDS Infernalis (Day 1) -- Ceph && Containers","description":"","frontmatter":{"title":"CDS Infernalis (Day 1) -- Ceph && Containers","date":"2015-03-06T00:00:00.000Z","updated":"2015-03-07T00:00:00.000Z","tags":["Ceph","Docker","Kubernetes","Distributed Storage","Container Storage"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2015/CDS_Infernalis_Day_1_--_Ceph_Containers.md","filePath":"posts/2015/CDS_Infernalis_Day_1_--_Ceph_Containers.md","lastUpdated":1780459816000}'),o={name:"posts/2015/CDS_Infernalis_Day_1_--_Ceph_Containers.md"};function p(n,e,s,a,C,_){return i(),r("div",null,[...e[0]||(e[0]=[l('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议时间</strong>： [请填写会议时间]</p><p><strong>参会人员</strong>： Sebastian、[其他参会人员]</p><p><strong>会议主题</strong>： Ceph 分布式存储 Docker 集成工作及 Ceph 作为容器存储提供商的讨论</p><p><strong>会议内容</strong>：</p><p><strong>一、Ceph Docker 集成工作</strong></p><ul><li>Sebastian 介绍了 Ceph Docker 集成工作的最新进展，包括： <ul><li>基于 GitHub 上的 soccer SF 项目进行了改进，并将其移至 get-up-st 环境中。</li><li>提供了官方的 Ceph Docker 镜像，包括监控器、OSD、MDS、Rgw 等组件。</li><li>支持 Ceph Web 界面（CIT）在 Rgw 上的集成，并已合并。</li><li>使用 etcd 进行分布式配置，方便快速部署 Ceph 集群。</li><li>考虑使用 comd 生成模板，以便在 console 和 etcd 中重用。</li><li>目前已有一些基于 Firefly 的镜像，计划创建更多分支以支持不同版本。</li><li>已解决 Docker 镜像中的 bug，并有人提出了自己的解决方案。</li></ul></li><li>讨论了 Ceph Docker 镜像的版本问题，以及如何支持不同版本。</li><li>讨论了 Ceph 与其他存储解决方案（如 Coros）的兼容性问题。</li></ul><p><strong>二、Ceph 作为容器存储提供商</strong></p><ul><li>讨论了如何将 Ceph 作为存储提供商集成到 Docker 和 Kubernetes 中。</li><li>讨论了 Docker 中的存储抽象（volume）模型，以及如何使用 Ceph 作为后端存储。</li><li>讨论了 Ceph 在 Kubernetes 中的集成方案，包括使用 csi 驱动程序。</li><li>讨论了在 Atomic 操作系统上集成 Ceph 的挑战，以及如何解决命名空间问题。</li><li>讨论了 Ceph 与其他存储解决方案（如 Coros）的兼容性问题。</li></ul><p><strong>三、行动计划</strong></p><ul><li>Sebastian 将继续推进 Ceph Docker 集成工作，并创建更多分支以支持不同版本。</li><li>讨论了 Ceph 与其他存储解决方案的兼容性问题，并计划进一步研究。</li><li>讨论了 Ceph 作为容器存储提供商的集成方案，并计划进一步研究。</li></ul><p><strong>四、其他</strong></p><ul><li>讨论了 Fedora 21 的发布计划，以及 Ceph 在 Fedora 21 上的支持。</li><li>讨论了 Ceph 在 Kubernetes 中的集成方案，并计划进一步研究。</li></ul><p><strong>五、总结</strong></p><p>本次会议讨论了 Ceph 分布式存储 Docker 集成工作和 Ceph 作为容器存储提供商的讨论，并制定了后续行动计划。会议重点涉及了 Ceph 的 Docker 集成、Ceph 作为容器存储提供商的集成方案、Ceph 与其他存储解决方案的兼容性以及 Fedora 和 Kubernetes 中的 Ceph 集成。</p><p><strong>改进说明</strong>：</p><ul><li>保留了会议的关键细节，包括 Ceph Docker 集成工作的进展、Ceph 作为容器存储提供商的讨论以及后续行动计划。</li><li>确保了计算机科学/ceph相关领域的英文原文关键词被保留。</li><li>简化了一些描述，以避免重复并提高可读性。</li></ul>',17)])])}const u=t(o,[["render",p]]);export{c as __pageData,u as default};
